INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62235812', 62235812, 'analyze_legacy', 'Lembaga Penyiaran Radio Republik Indonesia', 'central', 'RRI YOGYAKARTA', 'Pemeliharaan Gedung/Bangunan Kantor Tidak Bertingkat (D.I. Yogyakarta)', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 38340000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 639, M2, @ 60000 )', '1. Pemeliharaan Gedung/Bangunan Kantor Tidak Bertingkat (D.I. Yogyakarta) ( 639, M2, @ 60000 );', 'Pengadaan jasa pemeliharaan gedung/bangunan kantor tidak bertingkat dimaksudkan untuk menjaga kondisi fisik, fungsi, dan kenyamanan bangunan agar tetap layak digunakan dalam menunjang kegiatan operasional perkantoran. Pemeliharaan dilakukan secara rutin maupun insidentil guna mencegah kerusakan serta memperpanjang umur pakai bangunan. Ruang lingkup pekerjaan meliputi pemeliharaan ringan bangunan satu lantai, antara lain perbaikan dinding, lantai, plafon, atap, pintu dan jendela, pengecekan serta perbaikan ringan instalasi listrik dan air, pengecatan minor, serta perawatan fasilitas pendukung lainnya. Pelaksanaan pekerjaan dilakukan sesuai standar teknis bangunan dan ketentuan keselamatan kerja yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 351194);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62235814', 62235814, 'analyze_legacy', 'Lembaga Penyiaran Radio Republik Indonesia', 'central', 'RRI YOGYAKARTA', 'Pemeliharaan Alat Musik', 'Jasa Lainnya', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 15000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Th, @ 15000000 )', '1. Pemeliharaan Alat Musik ( 1, Th, @ 15000000 );', 'Pemeliharaan alat musik tradisional, khususnya gamelan dan alat musik Jawa lawas, dimaksudkan untuk menjaga kualitas bunyi, keutuhan material, serta nilai artistik dan historis instrumen agar tetap layak digunakan dan dilestarikan. Pekerjaan pemeliharaan dilakukan oleh tenaga ahli yang memiliki kompetensi dan pengalaman khusus dalam perawatan alat musik tradisional, mengingat karakter bahan dan teknik penanganannya tidak dapat disamakan dengan alat musik modern. Ruang lingkup pemeliharaan meliputi pembersihan logam gamelan (brasso) menggunakan metode tradisional yang aman, perawatan permukaan agar tidak merusak patina asli, penyetelan nada (setem) melalui penarikan tali pluntur atau setem ular, penyesuaian resonansi, serta pemeriksaan kondisi fisik instrumen secara menyeluruh. Seluruh pekerjaan dilakukan secara hati-hati, manual, dan sesuai kaidah perawatan alat musik tradisional, tanpa mengubah bentuk, karakter suara, maupun nilai keaslian instrumen.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 351195);
