INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62280916', 62280916, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA BANTAENG01', 'Belanja Keperluan Perkantoran', 'Jasa Lainnya', 'E-Purchasing', 'Sulawesi Selatan, Bantaeng (Kab.)', 349323000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '78 ob', 'Pengadaan Tenaga : 1. Satpam 2. Petugas Kebersihan', '1. Satpam Persyaratan Umum Kewarganegaraan: Warga Negara Indonesia (WNI). Kesehatan: Sehat jasmani dan rohani, bebas narkoba, tidak buta warna. Usia: Minimal 18 tahun, maksimal 30-35 tahun (tergantung jenjang/perusahaan). Pendidikan: Minimal SLTA/sederajat. Fisik: Tinggi badan minimal 165 cm (pria) dan 160 cm (wanita). Dokumen: SKCK (Surat Keterangan Catatan Kepolisian). Kelakuan: Berkelakuan baik, tidak bertindik/bertato (tergantung kebijakan). Pelatihan dan Jenjang Gada Pratama: Pelatihan dasar untuk menjadi satpam pemula. Setelah lulus, dapatkan KTA dan sertifikat. Kemampuan komunikasi yang baik dalam situasi tekanan, Keterampilan fisik dan kesiapan menghadapi situasi darurat, Kemampuan bekerja sama dalam tim, Bertanggung jawab dan motivasi tinggi. 2. Petugas Kebersihan 1. Kualifikasi & Kemampuan Umum Kesehatan: Surat keterangan sehat & bebas narkoba. Etika: Profesional, jujur, disiplin, mampu bekerja mandiri dan tim, berorientasi pada Service Excellent. Pendidikan & Pengalaman: Minimal SMA/sederajat, pengalaman kerja 1-3 tahun (opsional, tergantung kebutuhan). Sertifikasi: Sertifikat kompetensi BNSP (jika ada). 2. Keterampilan Teknis Pengetahuan: Teknik pembersihan lantai, dinding, kaca, furnitur, toilet, area luar (taman). Penggunaan: Peralatan (sapu, pel, vacuum, polisher) dan bahan kimia pembersih yang tepat. Penanganan: Sampah, area spesifik (toilet, pantry, ruang operasi/HCU). K3: Memahami dan menerapkan Kesehatan & Keselamatan Kerja (K3). 3. Tanggung Jawab & Tugas Utama Harian: Menyapu, mengepel, membersihkan meja, toilet, kaca, wastafel, mengambil & membuang sampah. Periodik: General cleaning, vacuuming karpet, membersihkan langit-langit, merawat taman/tanaman. Kontrol: Memastikan ketersediaan sabun, tisu, dll., dan melaporkan kerusakan. 4. Peralatan yang Dibutuhkan (Contoh) Sapu, pengki, pel, ember, kain lap, sikat, vacuum cleaner. Pembersih kaca, stainless, lantai, toilet (sesuai MSDS). Alat pelindung diri (masker, sarung tangan). 5. Jadwal Kerja & SOP Pelaksanaan sesuai jadwal harian/mingguan/bulanan (misal: pagi bersih ruangan, siang kontrol toilet/kaca). Melaksanakan pekerjaan sesuai Standard Operating Procedure (SOP) yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 355960);
